// Фикстура теста CLI-реплея (tests/agent/replay_cli_test.py).
//
// Герой едет вправо ровно пока удерживается Right: ничего, кроме ввода, на
// движение не влияет (гравитация выключена, тела нет, случайности нет).
// Поэтому запись ввода обязана воспроизвести ту же позицию до пикселя.
const SPEED = 120;

$.ready(() => {
    $.world.gravity(0, 0).color('#000000');
    $('<sprite>', { id: 'hero', w: 16, h: 16 }).at(0, 100).appendTo($.world);
});

$.update(() => {
    if ($.input.down('right')) {
        $('#hero').move(SPEED * $.time.delta(), 0);
    }
});
